	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestMainEntryPoint(t *testing.T) {
	tests := []struct {
		name        string
		invocations int
	}{
		{
			name:        "single invocation",
			invocations: 1,
		},
		{
			name:        "repeated invocations",
			invocations: 3,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for range tt.invocations {
				main()
			}
		})
	}
}

